package org.jsoup.safety;

import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.mockito.Mock;
import org.mockito.Mockito;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

@RunWith(JUnit4.class)
public class SafelistTest {

    @BeforeClass
    public static void setup() {
        // Initialize mocks here if needed
    }

    @Test
    public void none_SafelistShouldBeEmpty() {
        Safelist safelist = Safelist.none();
        assertTrue(safelist.isEmpty());
    }

    @Test
    public void simpleText_SafelistShouldAllowBasicTagsAndAttributes() {
        Safelist safelist = Safelist.simpleText();
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeAttribute("img", null, null));
        assertTrue(safelist.getEnforcedAttributes("img").containsKey("src"));
    }

    @Test
    public void basic_SafelistShouldNotAllowTagsAndAttributes() {
        Safelist safelist = Safelist.basic();
        assertFalse(safelist.isSafeTag("script"));
        assertFalse(safelist.isSafeAttribute("script", null, null));
    }

    @Test
    public void basicWithImages_SafelistShouldAllowTagsAndAttributes() {
        Safelist safelist = Safelist.basicWithImages();
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeAttribute("img", null, null));
        assertFalse(safelist.isSafeTag("script"));
    }

    @Test
    public void relaxed_SafelistShouldAllowTagsAndAttributes() {
        Safelist safelist = Safelist.relaxed();
        assertTrue(safelist.isSafeTag("script"));
        assertTrue(safelist.isSafeAttribute("script", null, null));
    }

    @Test
    public void addTags_SafelistAddTagsShouldBeAllowed() {
        Safelist safelist = Safelist.none();
        Set<String> tags = new HashSet<>();
        safelist.addTags(tags.toArray(new String[0]));
        assertTrue(safelist.isSafeTag("tag"));
    }

    @Test
    public void removeTags_SafelistRemoveTagsShouldBeAllowed() {
        Safelist safelist = Safelist.none();
        Set<String> tags = new HashSet<>();
        safelist.removeTags(tags.toArray(new String[0]));
        assertFalse(safelist.isSafeTag("tag"));
    }

    @Test
    public void addAttributes_SafelistAddAttributesShouldBeAllowed() {
        Safelist safelist = Safelist.simpleText();
        safelist.addAttributes("img", "src", "https://example.com");
        assertTrue(safelist.getEnforcedAttributes("img").containsKey("src"));
    }

    @Test
    public void removeAttributes_SafelistRemoveAttributesShouldBeAllowed() {
        Safelist safelist = Safelist.simpleText();
        safelist.removeAttributes("img", "src");
        assertFalse(safelist.getEnforcedAttributes("img").containsKey("src"));
    }

    @Test
    public void addEnforcedAttribute_SafelistAddEnforcedAttributesShouldBeAllowed() {
        Safelist safelist = Safelist.none();
        safelist.addEnforcedAttribute("tag", "attribute", "value");
        assertTrue(safelist.getEnforcedAttributes("tag").containsKey("attribute"));
    }

    @Test
    public void removeEnforcedAttribute_SafelistRemoveEnforcedAttributesShouldBeAllowed() {
        Safelist safelist = Safelist.none();
        safelist.removeEnforcedAttribute("tag", "attribute");
        assertFalse(safelist.getEnforcedAttributes("tag").containsKey("attribute"));
    }

    @Test
    public void preserveRelativeLinks_SafelistPreserveRelativeLinksShouldBeAllowed() {
        Safelist safelist = Safelist.relaxed();
        safelist.preserveRelativeLinks(true);
        assertTrue(safelist.isSafeTag("a"));
    }

    @Test
    public void addProtocols_SafelistAddProtocolsShouldBeAllowed() {
        Safelist safelist = Safelist.none();
        safelist.addProtocols("tag", "attribute", "https://example.com");
